const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args || source.payload?.args || {};
const payload = source.payload || {};
const message = source.message || payload.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const raw = String(source.rawText || source.text || message.text || payload.text || '').trim();

function clean(value) {
  return String(value || '').trim();
}

const query = clean(
  source.query ||
  args.query ||
  payload.query ||
  raw.replace(/^(tim mail|tìm mail|tim email|tìm email|search mail|search email|tim kiem mail|tìm kiếm mail|tim kiem email|tìm kiếm email)\s*/i, '')
);
const sender = clean(source.sender || args.sender || payload.sender);
const subject = clean(source.subject || args.subject || payload.subject);
const limit = Number(source.limit || args.limit || payload.limit || 3) || 3;
const hasQuery = Boolean(query || sender || subject);
const guidance = '🔎 <b>Tìm kiếm email</b>\n\nVí dụ: tìm mail từ Google';

return [{
  json: {
    ...source,
    payload,
    message,
    chatId,
    query,
    sender,
    subject,
    limit,
    hasQuery,
    response: hasQuery ? '' : guidance
  }
}];

const source = $('Chuan Bi Tim Email').item.json || {};

const pickFirst = (...values) => {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  }
  return '';
};

const formatDate = (value) => {
  if (value === undefined || value === null || value === '') return '';
  const normalized = /^\d+$/.test(String(value)) ? Number(value) : value;
  const date = new Date(normalized);
  return Number.isNaN(date.getTime())
    ? ''
    : date.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
};

const cleanText = (value = '') => String(value)
  .replace(/[\u034f\u061c\u115f\u1160\u17b4\u17b5\u180e\u200b-\u200f\u202a-\u202e\u2060-\u206f\ufeff]/g, '')
  .replace(/\s+/g, ' ')
  .trim();

const buildMailLink = (email) => {
  const threadId = pickFirst(email.threadId);
  const messageId = pickFirst(email.id);
  if (threadId) return `https://mail.google.com/mail/u/0/#inbox/${threadId}`;
  if (messageId) return `https://mail.google.com/mail/u/0/#inbox/${messageId}`;
  return '';
};

const rows = $input.all()
  .map((item) => item.json || {})
  .filter((email) => email.id || email.subject || email.Subject || email.from || email.From || email.snippet)
  .slice(0, 3);

const query = pickFirst(source.query, source.sender, source.subject);
const links = [];
let text = '';

if (!rows.length) {
  text = query
    ? `Mia chưa tìm thấy email nào khớp với "${query}".`
    : 'Mia chưa tìm thấy email phù hợp.';
} else {
  text = query
    ? `Mia tìm thấy ${rows.length} email khá khớp với "${query}":`
    : `Mia tìm thấy ${rows.length} email phù hợp:`;

  rows.forEach((email, index) => {
    const subject = pickFirst(email.subject, email.Subject, email.payload?.headers?.find((h) => h.name === 'Subject')?.value) || 'Không có tiêu đề';
    const from = cleanText(pickFirst(email.from?.value?.[0]?.name, email.from?.value?.[0]?.address, email.From, email.from, email.payload?.headers?.find((h) => h.name === 'From')?.value)) || 'Không rõ người gửi';
    const date = formatDate(pickFirst(email.date, email.Date, email.internalDate));
    const snippet = cleanText(pickFirst(email.snippet));
    const link = buildMailLink(email);

    text += `\n${index + 1}. ${subject} — từ ${from}`;
    if (date) text += `, lúc ${date}`;
    if (snippet) text += `\n   ${snippet.slice(0, 180)}`;
    if (link && !links.includes(link)) links.push(link);
  });

  if (links.length) {
    text += '\n\nMở nhanh email:';
    links.slice(0, 3).forEach((link, index) => {
      text += `\n${index + 1}. ${link}`;
    });
  }
}

return [{
  json: {
    ok: true,
    tool: 'gmail.search_email',
    chatId: source.chatId || '',
    text: text.trim(),
    links: links.slice(0, 3),
    result: { emails: rows },
    meta: { query, count: rows.length }
  }
}];

const source = $json || {};

function decodeEntities(value = '') {
  return String(value)
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'");
}

function htmlToPlainText(value = '') {
  return decodeEntities(String(value || ''))
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<li>/gi, '- ')
    .replace(/<\/h\d>/gi, '\n')
    .replace(/<a[^>]*href="([^"]+)"[^>]*>(.*?)<\/a>/gi, '$2: $1')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\s+([,.;:!?])/g, '$1')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const target =
  source.query ||
  source.docName ||
  source.sheetName ||
  source.fileName ||
  source.folderName ||
  source.targetName ||
  source.title ||
  source.summary ||
  source.rawText ||
  source.text ||
  '';

let text = htmlToPlainText(source.response || source.text || source.error || '');
if (!text) {
  text = target
    ? `Mia chưa xử lý được yêu cầu với "${target}". Bạn kiểm tra lại thông tin đầu vào giúp Mia nhé.`
    : 'Mia chưa đủ thông tin để xử lý yêu cầu này.';
}

return [{
  json: {
    ok: false,
    tool: source.tool || source.workflowKey || '',
    chatId: source.chatId || '',
    text,
    links: [],
    result: {},
    meta: {
      target: String(target || '').trim(),
      reason: source.hasTarget === false || source.isReady === false ? 'missing_required_input' : 'not_found_or_not_applicable'
    }
  }
}];
